        if (candidate === -1 && leftU <= rightU) {
          const id = orderU[rightU];
          if (u[id] > u[cur] + d) candidate = id;
        }
        if (candidate === -1 && leftV <= rightV) {
          const id = orderV[leftV];
          if (v[id] < v[cur] - d) candidate = id;
        }
