          if (cu < minU[c]) minU[c] = cu;
          if (cu > maxU[c]) maxU[c] = cu;
          if (cv < minV[c]) minV[c] = cv;
          if (cv > maxV[c]) maxV[c] = cv;
        } else {
          minU[c] = maxU[c] = cu;
          minV[c] = maxV[c] = cv;
        }
        count[c]++;

        color[candidate] = c;
        alive[candidate] = 0;
        queue[tail++] = candidate;

        while (leftU < n && !alive[orderU[leftU]]) leftU++;
        while (rightU >= 0 && !alive[orderU[rightU]]) rightU--;
        while (leftV < n && !alive[orderV[leftV]]) leftV++;
        while (rightV >= 0 && !alive[orderV[rightV]]) rightV--;
      }
    }
  }
  return true;
}

while (high - low > 1) {
  const mid = Math.floor((low + high) / 2);
  if (feasible(mid)) high = mid;
